/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.8 Confirm shipments
/// </summary>
[ExtensionOf(tableStr(HMIMMultimodalDG))]
final class METHMIMMultimodalDGTbl_Extension
{
}

Method.Source:
/// <summary>
/// Determines whether a record in the <c>HMIMMultimodalDG</c> table exists for a specified custom shipment Id.
/// </summary>
/// <param name="_shipmentId">
///  The custom shipment Id of the <c>HMIMMultimodalDG</c> to find.
/// </param>
/// <returns>
/// true if the specified record exists; otherwise, false.
/// </returns>
public static boolean METExistShipmentId(METShipmentId _shipmentId)
{
    return _shipmentId && (select firstonly RecId from HMIMMultimodalDG
                                                 where HMIMMultimodalDG.METShipmentId == _shipmentId).RecId != 0;
}
